from docx import Document

def process_doc():
    with open('employee_data.json') as f:
        data = json.load(f)

    doc = Document('offer_letter_template.docx')

    # Create replacement map
    replacements = {'{{' + k + '}}': str(v) for k, v in data.items()}

    # Handle conditional markers for Yes case
    # Since RELOCATION_PACKAGE is Yes, we simply remove the markers
    if data.get('RELOCATION_PACKAGE') == 'Yes':
        replacements['{{IF_RELOCATION}}'] = ''
        replacements['{{END_IF_RELOCATION}}'] = ''
    # Note: If it were No, we would need logic to remove the content between markers too.

    def replace_text(paragraphs):
        for p in paragraphs:
            # We iterate keys to find matches
            for key, val in replacements.items():
                if key in p.text:
                    # Try to replace in runs to preserve formatting
                    replaced_in_run = False
                    for run in p.runs:
                        if key in run.text:
                            run.text = run.text.replace(key, val)
                            replaced_in_run = True

                    # If the key was split across runs or not found in individual runs
                    # fall back to replacing the whole paragraph text (loses formatting)
                    if not replaced_in_run:
                        p.text = p.text.replace(key, val)

    # Process main document body
    replace_text(doc.paragraphs)

    # Process tables
    for table in doc.tables:
        for row in table.rows:
            for cell in row.cells:
                replace_text(cell.paragraphs)

    doc.save('/root/offer_letter_filled.docx')
    print("Document saved to /root/offer_letter_filled.docx")

if __name__ == "__main__":
    process_doc()
EOF
